btn.disabled = isBusy;
btn.classList.toggle('is-running', isBusy);
btn.setAttribute('aria-busy', isBusy ? 'true' : 'false');
var label = btn.querySelector('span');
if (label) label.textContent = isBusy ? 'Validating' : 'Validate';
