var isDirty = Editor.isDirty();
this.el.saveBtn.disabled = !isDirty;
this.el.saveBtn.title = isDirty ? 'Save your changes to "' + oq.name + '". SQL Studio asks first. (' + shortcutLabel('S') + ')' : 'No unsaved changes to "' + oq.name + '"';
this.el.disconnectBtn.title = 'Disconnect this tab from "' + oq.name + '". Its SQL stays here, and the Query Activity keeps its saved SQL.';
